"""The hand-drawn part polygons for every creature, written out as the specs build.py reads.

Coordinates are pixels of the cut-out picture in tools/puppets/src/. Edit here, then run
    python tools/puppets/make_specs.py && python tools/puppets/build.py <name>
"""
import json


def part(name, parent, pivot, z, poly):
    return {'name': name, 'parent': parent, 'pivot': pivot, 'z': z, 'poly': poly}


def save(name, origin, parts, **extra):
    with open(f'tools/puppets/specs/{name}.json', 'w') as f:
        json.dump({'origin': origin, 'parts': parts, **extra}, f)


